-- [F-086] travel_form: creaturemodeldata: 4 inserts, 0 updates, 0 deletes

/* Mists of Pandaria travel forms (Alliance and Horde), and the Battle for Azeroth ones of the Zandalari Troll
   and Kul Tiran */
DELETE FROM `creaturemodeldata` WHERE `id` IN (@DruidTravelAllianceModel, @DruidTravelHordeModel);

DELETE FROM `creaturemodeldata` WHERE `id` IN (@DruidTravelZandalariTrollModel, @DruidTravelKulTiranModel);
